pub fn run(config: Config) -> io::Result<()> {
    let shutdown = Arc::new(AtomicBool::new(false));
    let _ = flag::register(SIGINT, shutdown.clone())?;
    let _ = flag::register(SIGTERM, shutdown.clone())?;

    let deadline = config.exit_after_time.map(|duration| Instant::now() + duration);
    let mut printer = Printer::new(config.speed_factor, config.instant_print_lines, deadline, shutdown);
    let mut rng = rand::thread_rng();
    let modules = if config.modules.is_empty() {
        ALL_MODULES.to_vec()
    } else {
        config.modules
    };

    let mut completed_modules = 0usize;
    while !printer.should_stop() {
        let module = *modules.choose(&mut rng).unwrap();
        let completed = run_module(module, &mut printer, &mut rng)?;
        if !completed || printer.should_stop() {
            break;
        }
        completed_modules += 1;
        if config
            .exit_after_modules
            .is_some_and(|limit| completed_modules >= limit)
        {
            break;
        }
    }

    printer.save_and_flush()
}

fn run_module<R: Rng + ?Sized>(
    module: ModuleKind,
    printer: &mut Printer,
    rng: &mut R,
) -> io::Result<bool> {
    match module {
        ModuleKind::Ansible => ansible_scene(printer, rng),
        ModuleKind::Bootlog => bootlog_scene(printer, rng),
        ModuleKind::Botnet => botnet_scene(printer, rng),
        ModuleKind::Bruteforce => bruteforce_scene(printer, rng),
        ModuleKind::Cargo => cargo_scene(printer, rng),
        ModuleKind::Cc => cc_scene(printer, rng),
        ModuleKind::Composer => composer_scene(printer, rng),
        ModuleKind::Cryptomining => cryptomining_scene(printer, rng),
        ModuleKind::DockerBuild => docker_build_scene(printer, rng),
        ModuleKind::DockerImageRm => docker_image_rm_scene(printer, rng),
        ModuleKind::Download => download_scene(printer, rng),
        ModuleKind::Julia => julia_scene(printer, rng),
        ModuleKind::KernelCompile => kernel_compile_scene(printer, rng),
        ModuleKind::Memdump => memdump_scene(printer, rng),
        ModuleKind::Mkinitcpio => mkinitcpio_scene(printer, rng),
        ModuleKind::Rkhunter => rkhunter_scene(printer, rng),
        ModuleKind::Simcity => simcity_scene(printer, rng),
        ModuleKind::Terraform => terraform_scene(printer, rng),
        ModuleKind::Uv => uv_scene(printer, rng),
        ModuleKind::Weblog => weblog_scene(printer, rng),
        ModuleKind::Wpt => wpt_scene(printer, rng),
    }
}

struct Printer {
    stdout: io::Stdout,
    speed_factor: f64,
    instant_lines_left: usize,
    deadline: Option<Instant>,
    shutdown: Arc<AtomicBool>,
}

impl Printer {
    fn new(
        speed_factor: f64,
        instant_lines_left: usize,
        deadline: Option<Instant>,
        shutdown: Arc<AtomicBool>,
    ) -> Self {
        Self {
            stdout: io::stdout(),
            speed_factor,
            instant_lines_left,
            deadline,
            shutdown,
        }
    }

    fn should_stop(&self) -> bool {
        self.shutdown.load(Ordering::Relaxed)
            || self.deadline.is_some_and(|deadline| Instant::now() >= deadline)
    }

    fn emit(&mut self, text: &str, base_delay: Duration) -> io::Result<bool> {
        if self.should_stop() {
            return Ok(false);
        }
        self.stdout.write_all(text.as_bytes())?;
        self.stdout.flush()?;
        self.after_emit(base_delay)
    }

    fn emit_line(&mut self, text: &str, base_delay: Duration) -> io::Result<bool> {
        if self.should_stop() {
            return Ok(false);
        }
        self.stdout.write_all(text.as_bytes())?;
        self.stdout.write_all(b"\n")?;
        self.stdout.flush()?;
        self.after_emit(base_delay)
    }

    fn save_and_flush(&mut self) -> io::Result<()> {
        self.stdout.write_all(b"Saving work to disk...\n")?;
        self.stdout.flush()
    }

    fn after_emit(&mut self, base_delay: Duration) -> io::Result<bool> {
        if self.instant_lines_left > 0 {
            self.instant_lines_left -= 1;
            return Ok(!self.should_stop());
        }

        let delay = scale_delay(base_delay, self.speed_factor);
        let start = Instant::now();
        while start.elapsed() < delay {
            if self.should_stop() {
                return Ok(false);
            }
            let remaining = delay.saturating_sub(start.elapsed());
            std::thread::sleep(min(remaining, Duration::from_millis(20)));
        }

        Ok(!self.should_stop())
    }
}

fn scale_delay(base_delay: Duration, speed_factor: f64) -> Duration {
    if base_delay.is_zero() {
        return Duration::ZERO;
    }
    Duration::from_secs_f64(base_delay.as_secs_f64() / speed_factor)
}

fn ms(value: u64) -> Duration {
    Duration::from_millis(value)
}

fn scene_end<R: Rng + ?Sized>(rng: &mut R, min_ms: u64, max_ms: u64) -> Instant {
    Instant::now() + Duration::from_millis(rng.gen_range(min_ms..=max_ms))
}

fn cargo_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 12_000, 18_000);
    while Instant::now() < end {
        let line = if rng.gen_bool(0.84) {
            format!(
                "\x1b[1;32m Downloading\x1b[0m {} {}",
                crate_name(rng),
                version(rng)
            )
        } else {
            format!(
                "\x1b[1;32m   Compiling\x1b[0m {} {}",
                crate_name(rng),
                version(rng)
            )
        };
        if !printer.emit_line(&line, ms(110))? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn cc_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 12_000, 18_000);
    while Instant::now() < end {
        let compiler = if rng.gen_bool(0.45) { "clang" } else { "gcc" };
        let line = if compiler == "clang" {
            format!(
                "{compiler} -c -O0 -Wall -Wold-style-definition -Wold-style-definition -Wno-parentheses -Wno-sign-compare -Wno-sign-compare {} -DNDEBUG -DNAMESPACE=lib -D_LIBS_REENTRANT -D_LIBS_REENTRANT -DMATH_LOOP -DNAMESPACE=lib -DNAMESPACE=lib -o {}",
                include_flags(rng, 18, 26),
                KERNEL_OBJECTS.choose(rng).unwrap()
            )
        } else {
            format!(
                "{compiler} -c -O2 -Wall -Wextra -Wno-sign-compare -Wno-sign-compare -Wno-parentheses -Wno-unknown-pragmas -Wold-style-definition -fPIC -fgnu89-inline -fPIC -march=x86-64 {} -DNDEBUG -D_LIBS_REENTRANT -DSHARED -o {}",
                include_flags(rng, 18, 26),
                KERNEL_OBJECTS.choose(rng).unwrap()
            )
        };
        if !printer.emit_line(&line, ms(95))? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn composer_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 10_000, 16_000);
    if !printer.emit_line(
        "\x1b[32mLoading composer repositories with package information\x1b[0m",
        ms(180),
    )? {
        return Ok(false);
    }
    if !printer.emit_line(
        "\x1b[32mUpdating dependencies (including require-dev)\x1b[0m",
        ms(200),
    )? {
        return Ok(false);
    }
    while Instant::now() < end {
        let line = format!(
            "  - Installing \x1b[32m{}\x1b[0m (\x1b[33m{}\x1b[0m): Loading from cache",
            composer_package(rng),
            version(rng)
        );
        if !printer.emit_line(&line, ms(130))? {
            return Ok(false);
        }
    }
    Ok(true)
}

