fn docker_build_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 8_000, 12_000);
    let total = rng.gen_range(140.0..220.0);
    let mut current = 0.0;
    while Instant::now() < end && current < total {
        let line = format!(
            "\rSending build context to Docker daemon  {:>6.2}MB",
            current
        );
        if !printer.emit(&line, ms(70))? {
            return Ok(false);
        }
        current += rng.gen_range(4.5..22.0);
    }
    Ok(true)
}

fn docker_image_rm_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 8_000, 13_000);
    while Instant::now() < end {
        let image = format!("{}/{}:{}", word(rng), word(rng), tag(rng));
        if !printer.emit_line(&format!("Untagged: {image}"), ms(90))? {
            return Ok(false);
        }
        if !printer.emit_line(
            &format!("Untagged: {image}@sha256:{}", hex(rng, 64)),
            ms(90),
        )? {
            return Ok(false);
        }
        for _ in 0..rng.gen_range(8..18) {
            if !printer.emit_line(&format!("Deleted: sha256:{}", hex(rng, 64)), ms(60))? {
                return Ok(false);
            }
            if Instant::now() >= end {
                break;
            }
        }
    }
    Ok(true)
}

fn download_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 8_000, 12_000);
    let filename = format!("{}.{ext}", download_name(rng), ext_for_download(rng));
    let mut pct = 0u8;
    while Instant::now() < end && pct < 100 {
        let filled = usize::from(pct) * 16 / 100;
        let partial = if filled > 0 { "=" } else { "" };
        let bar = format!(
            "{partial}{}{}",
            "█".repeat(filled.min(15)),
            " ".repeat(16usize.saturating_sub(filled))
        );
        let line = format!(
            "\x1b[2K\x1b[0G{filename:<18}{pct:>3}%[{bar}] {:>4.2}MiB    {:>5.2}MiB/s   eta {}s",
            rng.gen_range(1.35..1.90),
            rng.gen_range(28.0..37.5),
            rng.gen_range(0..5)
        );
        if !printer.emit(&line, ms(55))? {
            return Ok(false);
        }
        pct = pct.saturating_add(rng.gen_range(1..=2));
    }
    Ok(true)
}

fn julia_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 9_000, 14_000);
    const HEADER: &str = concat!(
        "               \x1b[1;32m_\x1b[0m\n",
        "   \x1b[1;34m_\x1b[0m       _ \x1b[1;31m_\x1b[0m\x1b[1;32m(_)\x1b[0m\x1b[1;35m_\x1b[0m     |  Documentation: https://docs.julialang.org\n",
        "  \x1b[1;34m(_)\x1b[0m     | \x1b[1;31m(_)\x1b[0m \x1b[1;35m(_)\x1b[0m    |\n",
        "   _ _   _| |_  __ _   |  Type \"?\" for help, \"]?\" for Pkg help.\n",
        "  | | | | | | |/ _` |  |\n",
        "  | | |_| | | | (_| |  |  Version 1.7.3 (2022-05-06)\n",
        " _/ |\\__'_|_|_|\\__'_|  |  Fedora 35 build\n",
        "|__/                   |\n\n",
        "\x1b[1;32mjulia>\x1b[0m "
    );
    if !printer.emit(HEADER, ms(180))? {
        return Ok(false);
    }
    while Instant::now() < end {
        let action = if rng.gen_bool(0.65) { "update" } else { "add" };
        let maybe_pkg = if action == "add" {
            format!(" {}", crate_name(rng))
        } else {
            String::new()
        };
        let line = format!(
            "\x1b[2K\x1b[0G\x1b[1;34m(RandomTweaks) pkg>\x1b[0m {action}{maybe_pkg}"
        );
        if !printer.emit(&line, ms(90))? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn kernel_compile_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 10_000, 14_000);
    let verbs = ["AR", "CC", "LD", "OBJCOPY"];
    while Instant::now() < end {
        let line = format!(
            "  {:<7} {}",
            verbs.choose(rng).unwrap(),
            KERNEL_OBJECTS.choose(rng).unwrap()
        );
        if !printer.emit_line(&line, ms(95))? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn memdump_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 7_000, 10_000);
    let mut addr = rng.gen_range(0x1000_0000_0000_0000u64..0xffff_ffff_ffff_0000u64);
    while Instant::now() < end {
        let mut bytes = [0u8; 16];
        rng.fill(&mut bytes);
        let left = bytes[..8]
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<Vec<_>>()
            .join(" ");
        let right = bytes[8..]
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<Vec<_>>()
            .join(" ");
        let ascii: String = bytes
            .iter()
            .map(|byte| {
                if byte.is_ascii_graphic() {
                    char::from(*byte)
                } else {
                    '.'
                }
            })
            .collect();
        let line = format!("{addr:016x}  {left}  {right}  |{ascii}|");
        if !printer.emit_line(&line, ms(65))? {
            return Ok(false);
        }
        addr = addr.wrapping_add(0x10);
    }
    Ok(true)
}

fn mkinitcpio_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 8_000, 12_000);
    while Instant::now() < end {
        if !printer.emit_line(
            "\x1b[1;32m==> \x1b[0m\x1b[1mBuilding image from preset: /etc/mkinitcpio.d/linux.preset: 'default'\x1b[0m",
            ms(160),
        )? {
            return Ok(false);
        }
        if !printer.emit_line(
            "\x1b[1;34m  -> \x1b[0m\x1b[1m-k /boot/vmlinuz-linux -c /etc/mkinitcpio.conf -g /boot/initramfs-linux.img\x1b[0m",
            ms(120),
        )? {
            return Ok(false);
        }
        let build = format!(
            "\x1b[1;32m==> \x1b[0m\x1b[1mStarting build: {}.{}.{}-{}.el{}.{}\x1b[0m",
            rng.gen_range(2..7),
            rng.gen_range(6..18),
            rng.gen_range(0..40),
            rng.gen_range(100..900),
            rng.gen_range(6..10),
            ["i686", "x86_64"].choose(rng).unwrap()
        );
        if !printer.emit_line(&build, ms(130))? {
            return Ok(false);
        }
        for hook in ["base", "udev", "resume", "autodetect", "modconf", "filesystems", "fsck"] {
            let line = format!(
                "\x1b[1;34m  -> \x1b[0m\x1b[1mRunning build hook: [{hook}]\x1b[0m"
            );
            if !printer.emit_line(&line, ms(120))? {
                return Ok(false);
            }
            if Instant::now() >= end {
                break;
            }
        }
    }
    Ok(true)
}

fn rkhunter_scene<R: Rng + ?Sized>(printer: &mut Printer, _rng: &mut R) -> io::Result<bool> {
    let start = Local::now().format("%a %d %b %Y %I:%M:%S %p %Z");
    let lines = [
        "Running Rootkit Hunter version 0.0.2 on localhost".to_owned(),
        String::new(),
        format!("Info: Start date is {start}"),
        String::new(),
        "Info: Detected operating system is 'Linux'".to_owned(),
        "Found O/S name: Ubuntu 0.1.7Info: Environment shell is /bin/bash; rkhunter is using dash".to_owned(),
        "Info: Using configuration file '/etc/rkhunter.conf'".to_owned(),
        "Info: Installation directory is '/usr'".to_owned(),
        "Info: Using language 'en'".to_owned(),
        "Info: Using '/var/lib/rkhunter/db' as the database directory".to_owned(),
        "Info: Using '/usr/share/rkhunter/scripts' as the support script directory".to_owned(),
        "Info: Using '/var/lib/rkhunter/tmp' as the temporary directory".to_owned(),
        String::new(),
        "Checking if the O/S has changed since last time...".to_owned(),
        "Info: Nothing seems to have changed.".to_owned(),
        "Info: Locking is not being used".to_owned(),
        String::new(),
        "Starting system checks...".to_owned(),
        String::new(),
