fn simcity_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 11_000, 16_000);
    while Instant::now() < end {
        let task = SIMCITY_TASKS.choose(rng).unwrap();
        for spinner in SPINNER.iter().cycle().take(rng.gen_range(16..36)) {
            let line = format!("[ ] {task}... {spinner}\r");
            if !printer.emit(&line, ms(70))? {
                return Ok(false);
            }
        }
        let (color, status) = match rng.gen_range(0..3) {
            0 => (31, "ABORTED"),
            1 => (34, "SUCCESS"),
            _ => (37, "OK"),
        };
        let line = format!("[o] \x1b[{color}m{task}... {status}\x1b[0m");
        if !printer.emit_line(&line, ms(110))? {
            return Ok(false);
        }
    }
    if !printer.emit_line("ALL DONE", ms(80))? {
        return Ok(false);
    }
    Ok(true)
}

fn terraform_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 8_000, 12_000);
    while Instant::now() < end {
        if !printer.emit_line("Acquiring state lock. This may take a few moments...", ms(140))? {
            return Ok(false);
        }
        for _ in 0..rng.gen_range(6..10) {
            let line = format!(
                "\x1b[1mgoogle_{}_{}.{}: {}...{}\x1b[0m",
                word(rng),
                word(rng),
                word(rng),
                terraform_action(rng),
                terraform_suffix(rng)
            );
            if !printer.emit_line(&line, ms(140))? {
                return Ok(false);
            }
            if Instant::now() >= end {
                break;
            }
        }
        if !printer.emit_line(String::new().as_str(), ms(20))? {
            return Ok(false);
        }
        let summary = format!(
            "Apply complete! Resources: {} added, {} changed, {} destroyed.",
            rng.gen_range(0..3),
            rng.gen_range(0..3),
            rng.gen_range(0..3)
        );
        if !printer.emit_line(&summary, ms(180))? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn uv_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
