}

fn botnet_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 9_000, 14_000);
    while Instant::now() < end {
        let total = rng.gen_range(1200..3200);
        let mut current = 0usize;
        while current < total && Instant::now() < end {
            let line = format!("\rEstablishing connections: {:>4}/{total}", current);
            if !printer.emit(&line, ms(3))? {
                return Ok(false);
            }
            current = min(total, current + rng.gen_range(4..18));
        }
        if !printer.emit_line("", ms(40))? {
            return Ok(false);
        }
        for cluster in 0..rng.gen_range(1..4) {
            let line = format!("  Cluster #{cluster:02} ({:>3} nodes)", rng.gen_range(42..140));
            if !printer.emit_line(&line, ms(120))? {
                return Ok(false);
            }
        }
    }
    Ok(true)
}

fn bruteforce_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 8_000, 13_000);
    if !printer.emit_line("=> Hashes to decrypt", ms(90))? {
        return Ok(false);
    }
    for _ in 0..3 {
        let line = format!("  {}", hex(rng, 64));
        if !printer.emit_line(&line, ms(70))? {
            return Ok(false);
        }
    }
    let mut progress = 0usize;
    while Instant::now() < end {
        let line = format!(
            "\r=> Extracting Rainbow Table [{}]",
            rainbow_progress(progress)
        );
        if !printer.emit(&line, ms(45))? {
            return Ok(false);
        }
        progress = (progress + 1) % RAINBOW.len();
    }
    Ok(true)
}

fn terraform_action<R: Rng + ?Sized>(rng: &mut R) -> &'static str {
    ["Still creating", "Refreshing state", "Destroying", "Modifying", "Creating", "Creation complete", "Destruction complete", "Modifications complete"]
        .choose(rng)
        .copied()
        .unwrap()
}

fn terraform_suffix<R: Rng + ?Sized>(rng: &mut R) -> String {
    if rng.gen_bool(0.55) {
        format!(" [id={}]", word(rng))
    } else {
        format!(" [{}s elapsed]", rng.gen_range(0..4))
    }
}

fn include_flags<R: Rng + ?Sized>(rng: &mut R, min_count: usize, max_count: usize) -> String {
    let count = rng.gen_range(min_count..=max_count);
    let mut text = String::new();
    for _ in 0..count {
        let dir = INCLUDE_DIRS.choose(rng).unwrap();
        let _ = write!(text, "-I{dir} ");
    }
    text.trim_end().to_owned()
}

fn version<R: Rng + ?Sized>(rng: &mut R) -> String {
    format!(
        "v{}.{}.{}",
        rng.gen_range(0..3),
        rng.gen_range(0..40),
        rng.gen_range(0..30)
    )
}

fn composer_package<R: Rng + ?Sized>(rng: &mut R) -> String {
    format!("{}/{}", word(rng), word(rng))
}

fn crate_name<R: Rng + ?Sized>(rng: &mut R) -> String {
    let count = rng.gen_range(1..=3);
    let separator = ["-", "_"].choose(rng).unwrap();
    (0..count)
        .map(|_| word(rng))
        .collect::<Vec<_>>()
        .join(separator)
}

fn download_name<R: Rng + ?Sized>(rng: &mut R) -> String {
    if rng.gen_bool(0.35) {
        format!("M{:04}", rng.gen_range(100..999))
    } else {
        crate_name(rng)
    }
}

fn ext_for_download<R: Rng + ?Sized>(rng: &mut R) -> &'static str {
    ["rpm", "tar.gz", "tar.xz", "zip", "bin", "deb"]
        .choose(rng)
        .copied()
        .unwrap()
}

fn tag<R: Rng + ?Sized>(rng: &mut R) -> &'static str {
    ["latest", "stable", "edge", "prod", "rc", "test"]
        .choose(rng)
        .copied()
        .unwrap()
}

fn word<R: Rng + ?Sized>(rng: &mut R) -> &'static str {
    WORDS.choose(rng).copied().unwrap()
}

fn host<R: Rng + ?Sized>(rng: &mut R) -> String {
    if rng.gen_bool(0.45) {
        ipv6(rng)
    } else {
        ipv4(rng)
    }
}

fn ipv4<R: Rng + ?Sized>(rng: &mut R) -> String {
    format!(
        "{}.{}.{}.{}",
        rng.gen_range(0..=255),
        rng.gen_range(0..=255),
        rng.gen_range(0..=255),
        rng.gen_range(0..=255)
    )
}

fn ipv6<R: Rng + ?Sized>(rng: &mut R) -> String {
    (0..8)
        .map(|_| format!("{:x}", rng.gen_range(0..=0xffff)))
        .collect::<Vec<_>>()
        .join(":")
}

fn hex<R: Rng + ?Sized>(rng: &mut R, len: usize) -> String {
    let mut text = String::with_capacity(len);
    for _ in 0..len {
        let _ = write!(text, "{:x}", rng.gen_range(0..16));
    }
    text
}

fn http_path<R: Rng + ?Sized>(rng: &mut R) -> String {
    let segments = rng.gen_range(1..=5);
    let mut path = (0..segments)
        .map(|_| word(rng))
        .collect::<Vec<_>>()
        .join("/");
    let ext = HTTP_EXTENSIONS.choose(rng).unwrap();
    path.push('/');
    path.push_str(&format!("{}.{}", crate_name(rng), ext));
    path
}

fn wpt_path<R: Rng + ?Sized>(rng: &mut R) -> String {
    format!(
        "{}/{}/test-{}.html",
        ["css", "html", "streams", "cookies", "manifest", "svg", "security"]
            .choose(rng)
            .unwrap(),
        format!("{}-{}", word(rng), word(rng)),
        rng.gen_range(10..500)
    )
}

fn test_assertion<R: Rng + ?Sized>(rng: &mut R) -> String {
    match rng.gen_range(0..5) {
        0 => format!(
            "assert_equals: expected {} but got {}",
            rng.gen_range(1..999),
            rng.gen_range(1..999)
        ),
        1 => format!(
            "assert_approx_equals: expected {} +/- {} but got {}",
            rng.gen_range(10..100),
            rng.gen_range(1..9),
            rng.gen_range(10..200)
        ),
        2 => format!(
            "assert_array_equals: expected property {} to be {} but got {}",
            rng.gen_range(1..10),
            rng.gen_range(1..10),
            rng.gen_range(1..10)
        ),
        3 => "assert_true: expected true but got false".to_owned(),
        _ => "assert_throws_dom: function \"() => test()\" threw object \"TypeError: undefined is not a function\" that is not a DOMException".to_owned(),
    }
}

fn rainbow_progress(progress: usize) -> String {
    let mut text = String::new();
    for (index, color) in RAINBOW.iter().enumerate() {
        let ch = if index < progress {
            '='
        } else if index == progress {
            SPINNER[index % SPINNER.len()]
        } else {
            ' '
        };
        let _ = write!(text, "\x1b[38;5;{color}m{ch}\x1b[0m");
    }
    text
}

