mod cli;
mod runtime;

use clap::ArgMatches;
use clap_complete::generate;
use clap_mangen::Man;
use cli::{build_cli, config_from_matches, module_name, CompletionShell, ALL_MODULES};
use std::io::{self, Write};
use std::path::Path;
use std::process::ExitCode;

fn main() -> ExitCode {
    match try_main() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) if err.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("{err}");
            ExitCode::FAILURE
        }
    }
}

fn try_main() -> io::Result<()> {
    let argv0 = std::env::args()
        .next()
        .and_then(|path| {
            Path::new(&path)
                .file_name()
                .map(|name| name.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| "executable".to_owned());

    let matches = build_cli(Some(&argv0)).get_matches();
    handle_static_outputs(&matches)?;

    let config = config_from_matches(&matches);
    runtime::run(config)
}

fn handle_static_outputs(matches: &ArgMatches) -> io::Result<()> {
    if let Some(shell) = matches.get_one::<CompletionShell>("print-completions") {
        let mut cmd = build_cli(None);
        generate(
            Into::<clap_complete::Shell>::into(*shell),
            &mut cmd,
            "genact",
            &mut io::stdout(),
        );
        return Ok(());
    }

    if matches.get_flag("print-manpage") {
        let mut buffer = Vec::new();
        Man::new(build_cli(None)).render(&mut buffer)?;
        io::stdout().write_all(&buffer)?;
        return Ok(());
    }

    if matches.get_flag("list-modules") {
        let mut stdout = io::stdout();
        stdout.write_all(b"Available modules:\n")?;
        for module in ALL_MODULES {
            writeln!(stdout, "  {}", module_name(module))?;
        }
        return Ok(());
    }

    Ok(())
}

