type actionKind int

const (
	actionRun actionKind = iota
	actionHelp
	actionVersion
	actionListModules
	actionPrintManpage
	actionPrintCompletions
)

type config struct {
	modules            []string
	speedFactor        float64
	instantPrintLines  int
	exitAfterTime      time.Duration
	hasExitAfterTime   bool
	exitAfterModules   int
	hasExitAfterModule bool
	inhibit            bool
	action             actionKind
	completionShell    string
}

type cliError struct {
	message string
}

func main() {
	binName := filepath.Base(os.Args[0])
	cfg, cliErr := parseArgs(binName, os.Args[1:])
	if cliErr != nil {
		_, _ = fmt.Fprint(os.Stderr, cliErr.message)
		os.Exit(2)
	}

	switch cfg.action {
	case actionHelp:
		_, _ = fmt.Printf(helpTemplate, binName)
		return
	case actionVersion:
		_, _ = fmt.Printf("genact %s\n", version)
		return
	case actionPrintCompletions:
		data, err := embedded.ReadFile("assets/completions/" + cfg.completionShell + ".txt")
		if err != nil {
			_, _ = fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		_, _ = os.Stdout.Write(data)
		return
	case actionPrintManpage:
		data, err := embedded.ReadFile("assets/manpage.txt")
		if err != nil {
			_, _ = fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		_, _ = os.Stdout.Write(data)
		return
	case actionListModules:
		_, _ = fmt.Fprintln(os.Stdout, "Available modules:")
		for _, module := range moduleNames {
			_, _ = fmt.Fprintf(os.Stdout, "  %s\n", module)
		}
		return
	}

	if err := run(cfg); err != nil {
		if errors.Is(err, syscall.EPIPE) {
			return
		}
		_, _ = fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func parseArgs(binName string, args []string) (config, *cliError) {
	cfg := config{
		speedFactor:       1,
		instantPrintLines: 0,
		action:            actionRun,
	}

	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			cfg.action = actionHelp
			return cfg, nil
		}
		if arg == "-V" || arg == "--version" {
			cfg.action = actionVersion
			return cfg, nil
		}
	}

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "-l" || arg == "--list-modules":
			cfg.action = actionListModules
		case arg == "--inhibit":
			cfg.inhibit = true
		case arg == "--print-manpage":
			if cfg.action != actionPrintCompletions {
				cfg.action = actionPrintManpage
			}
		case arg == "-m" || arg == "--modules":
			value, next, err := nextValue(binName, args, i, arg, "MODULES")
			if err != nil {
				return cfg, err
			}
			i = next
			if !contains(moduleNames, value) {
				return cfg, invalidEnumError(value, "--modules <MODULES>", moduleNames)
			}
			cfg.modules = append(cfg.modules, value)
		case strings.HasPrefix(arg, "--modules="):
			value := strings.TrimPrefix(arg, "--modules=")
			if !contains(moduleNames, value) {
				return cfg, invalidEnumError(value, "--modules <MODULES>", moduleNames)
			}
			cfg.modules = append(cfg.modules, value)
		case arg == "-s" || arg == "--speed-factor":
			value, next, err := nextValue(binName, args, i, arg, "SPEED_FACTOR")
			if err != nil {
				return cfg, err
			}
			i = next
			speed, speedErr := parseSpeedFactor(value)
			if speedErr != nil {
				return cfg, invalidValueError(value, "--speed-factor <SPEED_FACTOR>", speedErr.Error())
			}
			cfg.speedFactor = speed
		case strings.HasPrefix(arg, "--speed-factor="):
			value := strings.TrimPrefix(arg, "--speed-factor=")
			speed, speedErr := parseSpeedFactor(value)
			if speedErr != nil {
				return cfg, invalidValueError(value, "--speed-factor <SPEED_FACTOR>", speedErr.Error())
			}
			cfg.speedFactor = speed
		case arg == "-i" || arg == "--instant-print-lines":
			value, next, err := nextValue(binName, args, i, arg, "INSTANT_PRINT_LINES")
			if err != nil {
				return cfg, err
			}
			i = next
			number, numErr := parsePositiveInt(value)
			if numErr != nil {
				return cfg, invalidValueError(value, "--instant-print-lines <INSTANT_PRINT_LINES>", numErr.Error())
			}
			cfg.instantPrintLines = number
		case strings.HasPrefix(arg, "--instant-print-lines="):
			value := strings.TrimPrefix(arg, "--instant-print-lines=")
			number, numErr := parsePositiveInt(value)
			if numErr != nil {
				return cfg, invalidValueError(value, "--instant-print-lines <INSTANT_PRINT_LINES>", numErr.Error())
			}
			cfg.instantPrintLines = number
		case arg == "--exit-after-time":
			value, next, err := nextValue(binName, args, i, arg, "EXIT_AFTER_TIME")
			if err != nil {
				return cfg, err
			}
			i = next
			duration, durationErr := parseHumanDuration(value)
			if durationErr != nil {
				return cfg, invalidValueError(value, "--exit-after-time <EXIT_AFTER_TIME>", durationErr.Error())
			}
			cfg.exitAfterTime = duration
			cfg.hasExitAfterTime = true
		case strings.HasPrefix(arg, "--exit-after-time="):
			value := strings.TrimPrefix(arg, "--exit-after-time=")
			duration, durationErr := parseHumanDuration(value)
			if durationErr != nil {
				return cfg, invalidValueError(value, "--exit-after-time <EXIT_AFTER_TIME>", durationErr.Error())
			}
			cfg.exitAfterTime = duration
			cfg.hasExitAfterTime = true
		case arg == "--exit-after-modules":
			value, next, err := nextValue(binName, args, i, arg, "EXIT_AFTER_MODULES")
			if err != nil {
				return cfg, err
			}
			i = next
			number, numErr := parsePositiveInt(value)
			if numErr != nil {
				return cfg, invalidValueError(value, "--exit-after-modules <EXIT_AFTER_MODULES>", numErr.Error())
			}
			cfg.exitAfterModules = number
			cfg.hasExitAfterModule = true
		case strings.HasPrefix(arg, "--exit-after-modules="):
			value := strings.TrimPrefix(arg, "--exit-after-modules=")
			number, numErr := parsePositiveInt(value)
			if numErr != nil {
				return cfg, invalidValueError(value, "--exit-after-modules <EXIT_AFTER_MODULES>", numErr.Error())
			}
			cfg.exitAfterModules = number
			cfg.hasExitAfterModule = true
		case arg == "--print-completions":
			value, next, err := nextValue(binName, args, i, arg, "shell")
			if err != nil {
				return cfg, err
			}
			i = next
			if !contains(completionShells, value) {
				return cfg, invalidEnumError(value, "--print-completions <shell>", completionShells)
			}
			cfg.completionShell = value
			cfg.action = actionPrintCompletions
		case strings.HasPrefix(arg, "--print-completions="):
			value := strings.TrimPrefix(arg, "--print-completions=")
			if !contains(completionShells, value) {
				return cfg, invalidEnumError(value, "--print-completions <shell>", completionShells)
			}
			cfg.completionShell = value
			cfg.action = actionPrintCompletions
		default:
			return cfg, unexpectedArgumentError(binName, arg)
		}
	}

	return cfg, nil
}

func nextValue(binName string, args []string, index int, flag string, valueName string) (string, int, *cliError) {
	if index+1 >= len(args) {
		return "", index, missingValueError(flag, valueName)
	}
	next := args[index+1]
	if strings.HasPrefix(next, "-") {
		return "", index, unexpectedArgumentError(binName, next)
	}
	return next, index + 1, nil
}

func run(cfg config) error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	rng := rand.New(rand.NewSource(time.Now().UnixNano()))
	printer := newPrinter(ctx, cfg.speedFactor, cfg.instantPrintLines, cfg.hasExitAfterTime, cfg.exitAfterTime)

	modules := cfg.modules
	if len(modules) == 0 {
		modules = moduleNames
	}

	completed := 0
	for !printer.shouldStop() {
		module := modules[rng.Intn(len(modules))]
		sceneComplete, err := runModule(module, printer, rng)
		if err != nil {
			return err
		}
		if !sceneComplete || printer.shouldStop() {
			break
		}
		completed++
		if cfg.hasExitAfterModule && completed >= cfg.exitAfterModules {
			break
		}
	}

	return printer.saveAndFlush()
}

type printer struct {
	writer           *bufio.Writer
	ctx              context.Context
	speedFactor      float64
	instantLinesLeft int
	deadline         time.Time
	hasDeadline      bool
}

func newPrinter(ctx context.Context, speedFactor float64, instantLines int, hasDeadline bool, duration time.Duration) *printer {
	p := &printer{
		writer:           bufio.NewWriter(os.Stdout),
		ctx:              ctx,
		speedFactor:      speedFactor,
		instantLinesLeft: instantLines,
		hasDeadline:      hasDeadline,
	}
	if hasDeadline {
		p.deadline = time.Now().Add(duration)
	}
	return p
}

func (p *printer) shouldStop() bool {
	select {
	case <-p.ctx.Done():
		return true
	default:
	}
	return p.hasDeadline && !time.Now().Before(p.deadline)
}

func (p *printer) emit(text string, delay time.Duration) (bool, error) {
	if p.shouldStop() {
		return false, nil
	}
	if _, err := p.writer.WriteString(text); err != nil {
		return false, err
	}
	if err := p.writer.Flush(); err != nil {
		return false, err
	}
	return p.afterEmit(delay)
}

func (p *printer) emitLine(text string, delay time.Duration) (bool, error) {
	if p.shouldStop() {
		return false, nil
	}
	if _, err := p.writer.WriteString(text); err != nil {
		return false, err
	}
	if err := p.writer.WriteByte('\n'); err != nil {
		return false, err
	}
	if err := p.writer.Flush(); err != nil {
		return false, err
	}
	return p.afterEmit(delay)
}

func (p *printer) saveAndFlush() error {
	if _, err := p.writer.WriteString("Saving work to disk...\n"); err != nil {
		return err
	}
	return p.writer.Flush()
}

func (p *printer) afterEmit(delay time.Duration) (bool, error) {
	if p.instantLinesLeft > 0 {
		p.instantLinesLeft--
		return !p.shouldStop(), nil
	}
	if delay <= 0 {
		return !p.shouldStop(), nil
	}
	scaled := time.Duration(float64(delay) / p.speedFactor)
	if scaled <= 0 {
		return !p.shouldStop(), nil
	}
	deadline := time.Now().Add(scaled)
	for time.Now().Before(deadline) {
		if p.shouldStop() {
			return false, nil
		}
		remaining := time.Until(deadline)
		if remaining > 20*time.Millisecond {
			remaining = 20 * time.Millisecond
		}
		time.Sleep(remaining)
	}
	return !p.shouldStop(), nil
}

