func cargoScene(p *printer, rng *rand.Rand) (bool, error) {
	end := sceneEnd(rng, 12*time.Second, 18*time.Second)
	for time.Now().Before(end) {
		var line string
		if rng.Float64() < 0.84 {
			line = fmt.Sprintf("\x1b[1;32m Downloading\x1b[0m %s %s", crateName(rng), semver(rng))
		} else {
			line = fmt.Sprintf("\x1b[1;32m   Compiling\x1b[0m %s %s", crateName(rng), semver(rng))
		}
		ok, err := p.emitLine(line, 110*time.Millisecond)
		if err != nil || !ok {
			return false, err
		}
	}
	return true, nil
}

