		}
		left := make([]string, 8)
		right := make([]string, 8)
		ascii := make([]rune, 16)
		for i := 0; i < 8; i++ {
			left[i] = fmt.Sprintf("%02x", bytes[i])
			right[i] = fmt.Sprintf("%02x", bytes[i+8])
