func parseSpeedFactor(input string) (float64, error) {
	value, err := strconv.ParseFloat(input, 64)
	if err != nil {
		return 0, errors.New("invalid float literal")
	}
	if value < 0.01 {
		return 0, errors.New("Speed factor must be larger than 0.01")
	}
	return value, nil
}

func parsePositiveInt(input string) (int, error) {
	value, err := strconv.Atoi(input)
	if err != nil || value < 0 {
		return 0, errors.New("invalid digit found in string")
	}
	return value, nil
}

func parseHumanDuration(input string) (time.Duration, error) {
	if input == "" || !unicode.IsDigit(rune(input[0])) {
		return 0, errors.New("expected number at 0")
	}
	var total time.Duration
	for i := 0; i < len(input); {
		start := i
		for i < len(input) && unicode.IsDigit(rune(input[i])) {
			i++
		}
		if start == i {
			return 0, fmt.Errorf("expected number at %d", i)
		}
		number, _ := strconv.Atoi(input[start:i])
		unitStart := i
		for i < len(input) && unicode.IsLetter(rune(input[i])) {
			i++
		}
		unit := input[unitStart:i]
		switch unit {
		case "h", "hr", "hrs", "hour", "hours":
			total += time.Duration(number) * time.Hour
		case "m", "min", "mins", "minute", "minutes":
			total += time.Duration(number) * time.Minute
		case "s", "sec", "secs", "second", "seconds":
			total += time.Duration(number) * time.Second
		case "ms":
			total += time.Duration(number) * time.Millisecond
		default:
			return 0, fmt.Errorf("unknown time unit %q", unit)
		}
	}
	return total, nil
}

func invalidValueError(value, flag, detail string) *cliError {
	return &cliError{
		message: fmt.Sprintf("error: invalid value '%s' for '%s': %s\n\nFor more information, try '--help'.\n", value, flag, detail),
	}
}

func invalidEnumError(value, flag string, choices []string) *cliError {
	var builder strings.Builder
	builder.WriteString(fmt.Sprintf("error: invalid value '%s' for '%s'\n", value, flag))
	builder.WriteString(fmt.Sprintf("  [possible values: %s]\n", strings.Join(choices, ", ")))
	if suggestion := closestMatch(value, choices); suggestion != "" {
		builder.WriteString("\n")
		builder.WriteString(fmt.Sprintf("  tip: a similar value exists: '%s'\n", suggestion))
	}
	builder.WriteString("\nFor more information, try '--help'.\n")
	return &cliError{message: builder.String()}
}

func unexpectedArgumentError(binName, arg string) *cliError {
	return &cliError{
		message: fmt.Sprintf("error: unexpected argument '%s' found\n\nUsage: %s [OPTIONS]\n\nFor more information, try '--help'.\n", arg, binName),
	}
}

func missingValueError(flag, valueName string) *cliError {
	return &cliError{
		message: fmt.Sprintf("error: a value is required for '%s <%s>' but none was supplied\n\nFor more information, try '--help'.\n", flag, valueName),
	}
}

func closestMatch(value string, candidates []string) string {
	best := ""
	bestSubseq := -1
	bestDistance := math.MaxInt
	for _, candidate := range candidates {
		subseq := subsequenceLen(value, candidate)
		distance := levenshtein(value, candidate)
		if subseq > bestSubseq || (subseq == bestSubseq && distance < bestDistance) {
			best = candidate
			bestSubseq = subseq
			bestDistance = distance
		}
	}
	if bestSubseq < 2 {
		return ""
	}
	return best
}

func subsequenceLen(a, b string) int {
	i := 0
	count := 0
	for j := 0; j < len(b) && i < len(a); j++ {
		if a[i] == b[j] {
			count++
			i++
		}
	}
	return count
}

func levenshtein(a, b string) int {
	da := make([]int, len(b)+1)
	for j := 0; j <= len(b); j++ {
		da[j] = j
	}
	for i := 1; i <= len(a); i++ {
		prev := da[0]
		da[0] = i
		for j := 1; j <= len(b); j++ {
			temp := da[j]
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			da[j] = minInt(minInt(da[j]+1, da[j-1]+1), prev+cost)
			prev = temp
		}
	}
	return da[len(b)]
}

func contains(items []string, value string) bool {
	for _, item := range items {
		if item == value {
			return true
		}
	}
	return false
}

func sceneEnd(rng *rand.Rand, minDelay, maxDelay time.Duration) time.Time {
	if maxDelay <= minDelay {
		return time.Now().Add(minDelay)
	}
	return time.Now().Add(minDelay + time.Duration(rng.Int63n(int64(maxDelay-minDelay))))
}

func includeFlags(rng *rand.Rand, minCount, maxCount int) string {
	count := rng.Intn(maxCount-minCount+1) + minCount
	parts := make([]string, count)
	for i := 0; i < count; i++ {
		parts[i] = "-I" + pick(rng, includeDirs)
	}
	return strings.Join(parts, " ")
}

func semver(rng *rand.Rand) string {
	return fmt.Sprintf("v%d.%d.%d", rng.Intn(3), rng.Intn(40), rng.Intn(30))
}

func crateName(rng *rand.Rand) string {
	count := rng.Intn(3) + 1
	separator := pick(rng, []string{"-", "_"})
	parts := make([]string, count)
	for i := 0; i < count; i++ {
		parts[i] = word(rng)
	}
	return strings.Join(parts, separator)
}

func downloadName(rng *rand.Rand) string {
	if rng.Float64() < 0.35 {
		return fmt.Sprintf("M%04d", rng.Intn(899)+100)
	}
	return crateName(rng)
}

func word(rng *rand.Rand) string {
	return pick(rng, words)
}

func host(rng *rand.Rand) string {
	if rng.Float64() < 0.45 {
		parts := make([]string, 8)
		for i := range parts {
			parts[i] = fmt.Sprintf("%x", rng.Intn(0x10000))
		}
		return strings.Join(parts, ":")
	}
	return fmt.Sprintf("%d.%d.%d.%d", rng.Intn(256), rng.Intn(256), rng.Intn(256), rng.Intn(256))
}

func hexString(rng *rand.Rand, length int) string {
	const digits = "0123456789abcdef"
	data := make([]byte, length)
	for i := range data {
		data[i] = digits[rng.Intn(len(digits))]
	}
	return string(data)
}

func httpPath(rng *rand.Rand) string {
	segments := rng.Intn(5) + 1
	parts := make([]string, 0, segments+1)
	for i := 0; i < segments; i++ {
		parts = append(parts, word(rng))
	}
	parts = append(parts, crateName(rng)+"."+pick(rng, httpExtensions))
	return strings.Join(parts, "/")
}

func wptPath(rng *rand.Rand) string {
	return fmt.Sprintf(
		"%s/%s-%s/test-%d.html",
		pick(rng, []string{"css", "html", "streams", "cookies", "manifest", "svg", "security"}),
		word(rng),
		word(rng),
		rng.Intn(490)+10,
	)
}

func testAssertion(rng *rand.Rand) string {
	switch rng.Intn(5) {
	case 0:
		return fmt.Sprintf("assert_equals: expected %d but got %d", rng.Intn(998)+1, rng.Intn(998)+1)
	case 1:
		return fmt.Sprintf("assert_approx_equals: expected %d +/- %d but got %d", rng.Intn(90)+10, rng.Intn(8)+1, rng.Intn(190)+10)
	case 2:
		return fmt.Sprintf("assert_array_equals: expected property %d to be %d but got %d", rng.Intn(9)+1, rng.Intn(9)+1, rng.Intn(9)+1)
	case 3:
		return "assert_true: expected true but got false"
	default:
		return `assert_throws_dom: function "() => test()" threw object "TypeError: undefined is not a function" that is not a DOMException`
	}
}

func rainbowProgress(progress int) string {
	var builder strings.Builder
	for index, color := range rainbow {
		ch := " "
		switch {
		case index < progress:
			ch = "="
		case index == progress:
			ch = string(spinner[index%len(spinner)])
		}
		builder.WriteString(fmt.Sprintf("\x1b[38;5;%dm%s\x1b[0m", color, ch))
	}
	return builder.String()
}

func pick[T any](rng *rand.Rand, items []T) T {
	return items[rng.Intn(len(items))]
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

