fn download_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 8_000, 12_000);
    let filename = format!("{}.{ext}", download_name(rng), ext_for_download(rng));
    let mut pct = 0u8;
    while Instant::now() < end && pct < 100 {
        let filled = usize::from(pct) * 16 / 100;
        let partial = if filled > 0 { "=" } else { "" };
        let bar = format!(
            "{partial}{}{}",
            "█".repeat(filled.min(15)),
            " ".repeat(16usize.saturating_sub(filled))
        );
        let line = format!(
            "\x1b[2K\x1b[0G{filename:<18}{pct:>3}%[{bar}] {:>4.2}MiB    {:>5.2}MiB/s   eta {}s",
            rng.gen_range(1.35..1.90),
            rng.gen_range(28.0..37.5),
            rng.gen_range(0..5)
        );
        if !printer.emit(&line, ms(55))? {
            return Ok(false);
        }
        pct = pct.saturating_add(rng.gen_range(1..=2));
    }
    Ok(true)
}

