fn memdump_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 7_000, 10_000);
    let mut addr = rng.gen_range(0x1000_0000_0000_0000u64..0xffff_ffff_ffff_0000u64);
    while Instant::now() < end {
        let mut bytes = [0u8; 16];
        rng.fill(&mut bytes);
        let left = bytes[..8]
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<Vec<_>>()
            .join(" ");
        let right = bytes[8..]
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<Vec<_>>()
            .join(" ");
        let ascii: String = bytes
            .iter()
            .map(|byte| {
                if byte.is_ascii_graphic() {
                    char::from(*byte)
                } else {
                    '.'
                }
            })
            .collect();
        let line = format!("{addr:016x}  {left}  {right}  |{ascii}|");
        if !printer.emit_line(&line, ms(65))? {
            return Ok(false);
        }
        addr = addr.wrapping_add(0x10);
    }
    Ok(true)
}

