        let task = SIMCITY_TASKS.choose(rng).unwrap();
        for spinner in SPINNER.iter().cycle().take(rng.gen_range(16..36)) {
            let line = format!("[ ] {task}... {spinner}\r");
            if !printer.emit(&line, ms(70))? {
                return Ok(false);
            }
        }
        let (color, status) = match rng.gen_range(0..3) {
            0 => (31, "ABORTED"),
            1 => (34, "SUCCESS"),
            _ => (37, "OK"),
        };
        let line = format!("[o] \x1b[{color}m{task}... {status}\x1b[0m");
        if !printer.emit_line(&line, ms(110))? {
            return Ok(false);
        }
    }
    if !printer.emit_line("ALL DONE", ms(80))? {
        return Ok(false);
    }
    Ok(true)
}

