fn wpt_scene<R: Rng + ?Sized>(printer: &mut Printer, rng: &mut R) -> io::Result<bool> {
    let end = scene_end(rng, 10_000, 16_000);
    let total = 26_201usize;
    let mut progress = 0usize;
    if !printer.emit_line(
        &format!("Running {total} tests in web-platform-tests"),
        ms(130),
    )? {
        return Ok(false);
    }
    if !printer.emit("\x1b[A\x1b[K[0/26201] No tests running.\n", ms(120))? {
        return Ok(false);
    }
    while Instant::now() < end {
        progress += rng.gen_range(1..=15);
        let active = (0..rng.gen_range(1..=8))
            .map(|_| format!("/{}", wpt_path(rng)))
            .collect::<Vec<_>>()
            .join(" ");
        let line = format!("\x1b[A\x1b[K[{progress}/{total}] {active} ");
        if !printer.emit_line(&line, ms(100))? {
            return Ok(false);
        }
        let block = if rng.gen_bool(0.45) {
            format!(
                "\x1b[A\x1b[K    ▶ Timed out in /{}\n    │ ERROR [expected {}] TIMEOUT test_{} {}\n",
                wpt_path(rng),
                if rng.gen_bool(0.75) { "PASS" } else { "FAIL" },
                word(rng),
                test_assertion(rng)
            )
        } else {
            format!(
                "\x1b[A\x1b[K    ▶ Unexpected subtest result in /{}:\n    │ ERROR [expected {}] {} test_{} {}\n    │   at http://web-platform.test:8000/resources/testharness.js:{}:{}\n    │   at {}\n    └   at {}\n",
                wpt_path(rng),
                if rng.gen_bool(0.75) { "PASS" } else { "FAIL" },
                if rng.gen_bool(0.2) { "PASS" } else { "FAIL" },
                word(rng),
                test_assertion(rng),
                rng.gen_range(600..2900),
                rng.gen_range(20..60),
                if rng.gen_bool(0.4) {
                    "<unknown>".to_owned()
                } else {
                    format!(
                        "http://web-platform.test:8000//{}:{}:{}",
                        wpt_path(rng),
                        rng.gen_range(8..150),
                        rng.gen_range(1..96)
                    )
                },
                if rng.gen_bool(0.55) {
                    "<unknown>".to_owned()
                } else {
                    format!(
                        "http://web-platform.test:8000//{}:{}:{}",
                        wpt_path(rng),
                        rng.gen_range(8..150),
                        rng.gen_range(1..96)
                    )
                }
            )
        };
        if !printer.emit(&block, ms(120))? {
            return Ok(false);
        }
    }
    Ok(true)
}

